ValidationRule.errorConditionFormula:
AND(
  CONTAINS(RecordType.DeveloperName,"FlatRock"),
  $Profile.Id <> "00e0H000001qCVbQAM",
  /* Profile id equals Data Systems" */
  ISNEW(),
  OR(
   ISBLANK(Account__c),
   Account.Account_ID__c = "001000000034Nt8AAE",
   /*Rithum account id*/
   Account.Account_ID__c = "0012A00002S3drbQAB",
   /*Rithum_Archive account id*/
   Account.Account_ID__c = "001F000000ku5TSIAY"
   /*Commerce Technologies, LLC dba CommerceHub account id*/
   )
)
